SELECT COUNT(*) FROM early_warnings ew
JOIN class_students cs ON ew.student_id = cs.student_id
WHERE ew.teacher_id = #{teacherId}
 AND cs.class_id = #{classId}
 AND ew.course_id = #{courseId}

SELECT COUNT(*) FROM early_warnings ew
JOIN class_students cs ON ew.student_id = cs.student_id
WHERE ew.teacher_id = #{teacherId} AND ew.is_resolved = 0
 AND cs.class_id = #{classId}
 AND ew.course_id = #{courseId}

SELECT COUNT(*) FROM early_warnings ew
JOIN class_students cs ON ew.student_id = cs.student_id
WHERE ew.teacher_id = #{teacherId} AND ew.warning_type = #{warningType}
 AND cs.class_id = #{classId}
 AND ew.course_id = #{courseId}

SELECT DISTINCT ew.*, u.name as studentName, c.course_name as courseName 
FROM early_warnings ew 
JOIN users u ON ew.student_id = u.id 
JOIN courses c ON ew.course_id = c.id 
JOIN class_students cs ON ew.student_id = cs.student_id
WHERE ew.teacher_id = #{teacherId}
 AND cs.class_id = #{classId}
 AND ew.course_id = #{courseId}
 AND ew.warning_type = #{warningType}


     AND ew.is_resolved = 0
     AND ew.is_resolved = 0
     AND ew.is_resolved = 1


ORDER BY ew.trigger_date DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(DISTINCT ew.id) FROM early_warnings ew 
JOIN class_students cs ON ew.student_id = cs.student_id
WHERE ew.teacher_id = #{teacherId}
 AND cs.class_id = #{classId}
 AND ew.course_id = #{courseId}
 AND ew.warning_type = #{warningType}


     AND ew.is_resolved = 0
     AND ew.is_resolved = 0
     AND ew.is_resolved = 1

mapper.update:
UPDATE early_warnings SET 

  is_resolved = 0


  is_resolved = 1, resolved_by = #{userId}, resolved_date = NOW()


  , resolved_note = #{updateDTO.resolvedNote}

WHERE id = #{warningId}

